/* nepui — Color Picker */

:is(.np-color-picker, [data-np-color-picker]) {
  --np-spacing: 0.25rem;
  --np-color-picker-width: calc(var(--np-spacing) * 64);
  --np-color-picker-gap: calc(var(--np-spacing) * 3);
  --np-color-picker-area-height: calc(var(--np-spacing) * 40);
  --np-color-picker-slider-size: calc(var(--np-spacing) * 3);
  --np-color-picker-thumb-size: calc(var(--np-spacing) * 5);
  --np-color-picker-radius: var(--np-radius-lg);
  --np-color-picker-thumb-ring: #fff;
  --np-color-picker-checker-a: var(--np-muted);
  --np-color-picker-checker-b: var(--np-background);

  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--np-color-picker-gap);
  box-sizing: border-box;
  inline-size: var(--np-color-picker-width);
  max-inline-size: 100%;
  color: var(--np-foreground);
}

:is(.np-color-picker, [data-np-color-picker])[data-disabled] {
  opacity: 0.55;
}

:is(.np-color-picker-hidden-input, [data-np-color-picker-hidden-input]) {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
}

:is(.np-color-picker-area, [data-np-color-picker-area]) {
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  block-size: var(--np-color-picker-area-height);
  flex: none;
  border-radius: var(--np-color-picker-radius);
  background: var(--color-area-background, none);
  box-shadow: inset 0 0 0 1px
    color-mix(in oklab, var(--np-foreground) 12%, transparent);
  cursor: crosshair;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

:is(.np-color-picker-area, [data-np-color-picker-area])[data-disabled] {
  cursor: not-allowed;
}

:is(.np-color-picker-area, [data-np-color-picker-area])[data-readonly] {
  cursor: default;
}

:is(.np-color-picker-area-canvas, [data-np-color-picker-area-canvas]) {
  position: absolute;
  inset: 0;
  inline-size: 100%;
  block-size: 100%;
  border-radius: inherit;
  pointer-events: none;
}

:is(
  .np-color-picker-area-thumb,
  .np-color-picker-slider-thumb,
  [data-np-color-picker-area-thumb],
  [data-np-color-picker-slider-thumb]
) {
  position: absolute;
  box-sizing: border-box;
  inline-size: var(--np-color-picker-thumb-size);
  block-size: var(--np-color-picker-thumb-size);
  translate: -50% -50%;
  border: 2px solid var(--np-color-picker-thumb-ring);
  border-radius: 9999px;
  background: var(--color-picker-color);
  box-shadow:
    0 0 0 1px rgb(0 0 0 / 0.3),
    0 1px 3px rgb(0 0 0 / 0.35),
    inset 0 0 0 1px rgb(0 0 0 / 0.15);
  outline: none;
  cursor: grab;
  touch-action: none;
}

:is(.np-color-picker-area-thumb, [data-np-color-picker-area-thumb]) {
  left: var(--area-x, 0%);
  top: var(--area-y, 0%);
}

:is(
  .np-color-picker-slider-thumb,
  [data-np-color-picker-slider-thumb]
)[data-orientation="horizontal"] {
  left: var(--color-slider-thumb-position, 0%);
  top: 50%;
}

:is(
  .np-color-picker-slider-thumb,
  [data-np-color-picker-slider-thumb]
)[data-orientation="vertical"] {
  left: 50%;
  top: var(--color-slider-thumb-position, 0%);
}

:is(
  .np-color-picker-area-thumb,
  .np-color-picker-slider-thumb,
  [data-np-color-picker-area-thumb],
  [data-np-color-picker-slider-thumb]
):active {
  cursor: grabbing;
}

:is(
  .np-color-picker-area-thumb,
  .np-color-picker-slider-thumb,
