:is(.np-color-picker-slider, [data-np-color-picker-slider]) {
  position: relative;
  box-sizing: border-box;
  flex: none;
  border-radius: 9999px;
  background: var(--color-slider-background, none);
  box-shadow: inset 0 0 0 1px
    color-mix(in oklab, var(--np-foreground) 12%, transparent);
  cursor: pointer;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
